import { guardianUpgrades } from '../../data/guardians/upgrades.data'
import type { GuardianDamagePool, GuardianTickDamageInput } from './types'

export const GUARDIAN_TYPE_HALF_DAMAGE = 3

export function guardianTickDamage(input: GuardianTickDamageInput): number {
  const delta = Math.max(0, input.endTime - input.startTime)
  let dmg = delta * input.damageMultiplier
  if (input.guardianType === GUARDIAN_TYPE_HALF_DAMAGE) {
    dmg *= 0.5
  }
  return dmg
}

export function depleteGuardianPool(
  pool: GuardianDamagePool,
  tickDamage: number,
): { pool: GuardianDamagePool, overflow: number } {
  const remaining = pool.end - pool.start
  if (tickDamage <= remaining) {
    return {
      pool: { start: pool.start + tickDamage, end: pool.end },
      overflow: 0,
    }
  }
  return {
    pool: { start: pool.end, end: pool.end },
    overflow: tickDamage - remaining,
  }
}

/**
 * The level a guardian's upgrade ladder starts at.
 *
 * Guardian upgrade tables do not all start at zero, so a level counted from the
 * bottom of the ladder ("normalized") and the level the table itself names
 * ("source") differ by this offset. `0` for a guardian with no upgrade table.
 */
export function getGuardianSourceMinLevel(guardianKey: string): number {
  const upgrades = guardianUpgrades[guardianKey as keyof typeof guardianUpgrades]
  if (!upgrades?.length) return 0
  return Math.min(...upgrades.map(entry => Number(entry.level)).filter(Number.isFinite))
}

/** A ladder-relative guardian level as the level the upgrade table names, or `null` when absent. */
export function normalizedGuardianLevelToSource(normalizedLevel: number | null | undefined, guardianKey: string): number | null {
  if (normalizedLevel == null || !Number.isFinite(normalizedLevel)) return null
  return Math.floor(Number(normalizedLevel) + getGuardianSourceMinLevel(guardianKey))
}

/** A level as the upgrade table names it, counted from the bottom of the guardian's ladder. */
export function guardianSourceLevelToNormalized(sourceLevel: number, guardianKey: string): number {
  return Math.floor(sourceLevel - getGuardianSourceMinLevel(guardianKey))
}

export const GUARDIAN_SAVE_KEYS = [
  'guardianChipLevel',
  'guardianChipUnlocked',
  'guardianCooldownTimers',
  'totalDamageByGuardian',
] as const
